SELECT MIN(order_purchase_timestamp) AS first_purchase, MAX(order_purchase_timestamp) AS latest_purchase, COUNT(*) AS orders, SUM(p.payment_value) AS payment_revenue
FROM orders o
JOIN order_payments p USING (order_id);

SELECT o.order_status, COUNT(DISTINCT o.order_id) AS orders, ROUND(SUM(p.payment_value),2) AS payment_revenue
FROM orders o JOIN order_payments p USING(order_id)
GROUP BY 1 ORDER BY payment_revenue DESC;

WITH x AS (
 SELECT COALESCE(pct.product_category_name_english,p.product_category_name,'unknown') AS category,
 COUNT(DISTINCT oi.order_id) AS orders, SUM(oi.price) AS revenue
 FROM order_items oi JOIN products p ON p.product_id=oi.product_id LEFT JOIN product_category_translation pct ON pct.product_category_name=p.product_category_name JOIN orders o ON o.order_id=oi.order_id WHERE o.order_status NOT IN ('canceled','unavailable') GROUP BY 1
)
SELECT ROUND(MEDIAN(orders),0) AS median_category_orders, ROUND(MEDIAN(revenue),2) AS median_category_revenue, ROUND(QUANTILE_CONT(orders,0.25),0) AS p25_orders, ROUND(QUANTILE_CONT(revenue,0.25),2) AS p25_revenue FROM x;

WITH x AS (
 SELECT COALESCE(pct.product_category_name_english,p.product_category_name,'unknown') AS category,
 COUNT(DISTINCT oi.order_id) AS orders, SUM(oi.price) AS revenue
 FROM order_items oi JOIN products p ON p.product_id=oi.product_id LEFT JOIN product_category_translation pct ON pct.product_category_name=p.product_category_name JOIN orders o ON o.order_id=oi.order_id WHERE o.order_status NOT IN ('canceled','unavailable') GROUP BY 1
)
SELECT category, orders, ROUND(revenue,2) revenue FROM x WHERE orders >= 100 ORDER BY revenue ASC LIMIT 20;

WITH x AS (
 SELECT COALESCE(pct.product_category_name_english,p.product_category_name,'unknown') AS category, AVG(r.review_score) AS rating, COUNT(DISTINCT r.order_id) reviews
 FROM order_items oi JOIN products p ON p.product_id=oi.product_id LEFT JOIN product_category_translation pct ON pct.product_category_name=p.product_category_name JOIN order_reviews r ON r.order_id=oi.order_id GROUP BY 1
)
SELECT category, ROUND(rating,2) AS avg_rating, reviews FROM x WHERE reviews >= 100 ORDER BY rating ASC LIMIT 20;

WITH r AS (
 SELECT category, AVG(review_score) rating, COUNT(*) reviews FROM (
 SELECT DISTINCT COALESCE(t.product_category_name_english,p.product_category_name,'unknown') category,r.order_id,r.review_score
 FROM order_items oi JOIN products p USING(product_id) LEFT JOIN product_category_translation t USING(product_category_name) JOIN order_reviews r USING(order_id)) GROUP BY 1
) SELECT category,reviews,ROUND(rating,2) avg_rating FROM r WHERE reviews>=100 ORDER BY rating ASC LIMIT 15;
